    static let linesLap: [Int: (pre: [KJLine], post: [KJLine])] = [
        201001: (pre: [
            KJLine(role: "n", face: "", ja: "もじが もどって しばらく たった ある日。", en: "Some time after the letters came back...", zh: "文字回來之後過了一陣子的某一天。", ko: "글자가 돌아오고 얼마 뒤의 어느 날."),
            KJLine(role: "yui", face: "yui_pose", ja: "わが なは ユイ！ やみの ことだまつかい！", en: "My name is Yui! Word-spirit user of the dark!", zh: "吾名結衣！黑暗的言靈使者！", ko: "내 이름은 유이! 어둠의 언령술사!"),
            KJLine(role: "y", face: "nk_nyan_surprised", ja: "…ソラの いとこ だにゃ。がいこくで そだったんだ。", en: "...She's Sora's cousin. She grew up abroad.", zh: "……是索拉的表妹喵。在國外長大的。", ko: "…소라의 사촌이다냥. 외국에서 자랐어."),
            KJLine(role: "yui", face: "yui_shy", ja: "ひらがなは よめるよ。でも かんじが にがて…。", en: "I can read hiragana. But kanji... not so much.", zh: "平假名我會唸。可是漢字不太行……", ko: "히라가나는 읽어. 근데 한자는 어려워…."),
            KJLine(role: "y", face: "nk_nyan_angry", ja: "たいへんだにゃ！ ようかいたちが こんどは かんじを たべてる！", en: "Trouble! This time the yokai are eating the kanji!", zh: "糟了喵！妖怪們這次在吃漢字！", ko: "큰일이다냥! 요괴들이 이번엔 한자를 먹고 있어!"),
            KJLine(role: "yui", face: "yui_pose", ja: "なら ちょうど いい！ かんじ、ぜんぶ おぼえて みせる！", en: "Perfect, then! I'll learn every kanji!", zh: "那正好！我要把漢字全部學會給你看！", ko: "그럼 딱 좋네! 한자, 전부 외워 보일게!")],
            post: [
]),
        201015: (pre: [
            KJLine(role: "yui", face: "yui_think", ja: "この かんじ… うえの ちいさい もじが あれば よめる！", en: "This kanji... I can read it with the tiny letters on top!", zh: "這個漢字……有上面的小字就看得懂！", ko: "이 한자… 위의 작은 글자가 있으면 읽을 수 있어!"),
            KJLine(role: "y", face: "nk_nyan_tip", ja: "それが ふりがな。かんじの よみかただにゃ。", en: "That's furigana. It tells you how to read the kanji.", zh: "那是假名注音，告訴你漢字怎麼唸喵。", ko: "그게 후리가나. 한자 읽는 법이다냥.")],
            post: [
]),
        201036: (pre: [
            KJLine(role: "kyubi", face: "boss_kyubi", ja: "また あったな。こんどは かんじで ばかして やろう。", en: "We meet again. This time I'll trick you with kanji.", zh: "又見面了。這次我用漢字來騙你們。", ko: "또 만났군. 이번엔 한자로 홀려 주마.")],
            post: [
            KJLine(role: "yui", face: "yui_cry", ja: "やった…！ はじめて かんじで かった！", en: "We did it...! My first win with kanji!", zh: "成功了……！第一次用漢字贏了！", ko: "해냈다…! 처음으로 한자로 이겼어!"),
            KJLine(role: "yui", face: "yui_shy", ja: "…じつは ね。おばあちゃんに てがみを かきたいの。かんじで。", en: "...Actually, I want to write a letter to my grandma. In kanji.", zh: "……其實啊，我想用漢字寫信給奶奶。", ko: "…사실은, 할머니께 한자로 편지를 쓰고 싶어."),
            KJLine(role: "y", face: "nk_nyan_gentle", ja: "じゃあ、たびを つづけよう。てがみが かける ように。", en: "Then let's keep traveling, until you can write it.", zh: "那就繼續旅行吧，直到你寫得出來。", ko: "그럼 여행을 계속하자. 편지를 쓸 수 있도록.")]),
        202001: (pre: [
            KJLine(role: "yui", face: "yui_smile", ja: "これが とうほく！ ゆきが きらきら！", en: "So this is Tohoku! The snow is sparkling!", zh: "這就是東北！雪閃閃發亮！", ko: "여기가 도호쿠! 눈이 반짝반짝!"),
            KJLine(role: "y", face: "nk_nyan_sniff", ja: "かっぱが また きゅうりを ねらってるにゃ。", en: "The kappa is after cucumbers again.", zh: "河童又在打小黃瓜的主意了喵。", ko: "갓파가 또 오이를 노리고 있다냥."),
            KJLine(role: "yui", face: "yui_pose", ja: "やみの ちからで… じゃなくて、かんじで たおす！", en: "With the power of darkness... no, with kanji!", zh: "用黑暗之力……不對，用漢字打倒他！", ko: "어둠의 힘으로… 가 아니라, 한자로 쓰러뜨린다!")],
            post: [
